import { useState } from "react";

function Dashboard() {
  const [jobs, setJobs] = useState([]);

  const [company, setCompany] = useState("");
  const [role, setRole] = useState("");

  const addJob = () => {
    if (!company || !role) {
      alert("Please fill all fields");
      return;
    }

    const newJob = {
      id: Date.now(),
      company,
      role,
    };

    setJobs([...jobs, newJob]);

    setCompany("");
    setRole("");
  };

  const deleteJob = (id) => {
    const updatedJobs = jobs.filter((job) => job.id !== id);
    setJobs(updatedJobs);
  };

  return (
    <div style={{ padding: "40px", fontFamily: "Arial" }}>
      <h1>Smart Job Tracker 🚀</h1>

      <div
        style={{
          display: "flex",
          gap: "10px",
          marginTop: "20px",
        }}
      >
        <input
          type="text"
          placeholder="Company Name"
          value={company}
          onChange={(e) => setCompany(e.target.value)}
          style={{ padding: "10px", width: "200px" }}
        />

        <input
          type="text"
          placeholder="Role"
          value={role}
          onChange={(e) => setRole(e.target.value)}
          style={{ padding: "10px", width: "200px" }}
        />

        <button
          onClick={addJob}
          style={{
            padding: "10px 20px",
            cursor: "pointer",
          }}
        >
          Add Job
        </button>
      </div>

      {/* Job List */}
      <div style={{ marginTop: "30px" }}>
        {jobs.map((job) => (
          <div
            key={job.id}
            style={{
              border: "1px solid gray",
              padding: "15px",
              marginBottom: "10px",
              borderRadius: "10px",
            }}
          >
            <h3>{job.company}</h3>
            <p>{job.role}</p>

            <button
              onClick={() => deleteJob(job.id)}
              style={{
                backgroundColor: "red",
                color: "white",
                padding: "8px",
                border: "none",
                cursor: "pointer",
              }}
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Dashboard;
